using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public sealed class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static ReportingConfiguration _reportingConfiguration = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is not null)
        {
            await _appHost.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_Responds_Relevantly()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Responds_Relevantly));

        var evaluator = new RelevanceTruthAndCompletenessEvaluator();
        var evalResult = await evaluator.EvaluateAsync(
            messages,
            response,
            new ChatConfiguration(chatClient));

        foreach (var metric in evalResult)
        {
            Assert.IsTrue(
                metric.Value is NumericMetricValue { InterpretedValue: >= EvaluationRating.Good },
                $"Metric '{metric.Key}' did not meet the quality threshold.");
        }
    }

    [TestMethod]
    public async Task Chat_Responds_Coherently()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that answers questions concisely."),
            new(ChatRole.User, "Explain what .NET Aspire is in one sentence.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Responds_Coherently));

        var evaluator = new CoherenceEvaluator();
        var evalResult = await evaluator.EvaluateAsync(
            messages,
            response,
            new ChatConfiguration(chatClient));

        foreach (var metric in evalResult)
        {
            Assert.IsTrue(
                metric.Value is NumericMetricValue { InterpretedValue: >= EvaluationRating.Good },
                $"Metric '{metric.Key}' did not meet the quality threshold.");
        }
    }

    [TestMethod]
    public async Task Chat_Responds_Fluently()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Write a short greeting for a new user of our application.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Responds_Fluently));

        var evaluator = new FluencyEvaluator();
        var evalResult = await evaluator.EvaluateAsync(
            messages,
            response,
            new ChatConfiguration(chatClient));

        foreach (var metric in evalResult)
        {
            Assert.IsTrue(
                metric.Value is NumericMetricValue { InterpretedValue: >= EvaluationRating.Good },
                $"Metric '{metric.Key}' did not meet the quality threshold.");
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        return DiskBasedReportingConfiguration.Create(storageRootPath: ".evaluation-results");
    }
}

