using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public sealed class ChatEvaluationTests
{
    private static IDistributedApplicationTestingBuilder _appHost = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_Responds_Relevantly()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

#pragma warning disable AIEVAL001
        var evaluators = new IEvaluator[] { new RelevanceTruthAndCompletenessEvaluator() };
#pragma warning restore AIEVAL001

        var reportingConfig = DiskBasedReportingConfiguration.Create(
            storageRootPath: ".evaluation-results",
            evaluators: evaluators,
            chatConfiguration: new ChatConfiguration(chatClient));

        await using var scenario = await reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Responds_Relevantly));

        var result = await scenario.EvaluateAsync(messages, response);

        AssertAllMetricsPassed(result);
    }

    [TestMethod]
    public async Task Chat_Responds_Coherently()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that answers questions concisely."),
            new(ChatRole.User, "Explain what .NET Aspire is in one sentence.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        var evaluators = new IEvaluator[] { new CoherenceEvaluator() };

        var reportingConfig = DiskBasedReportingConfiguration.Create(
            storageRootPath: ".evaluation-results",
            evaluators: evaluators,
            chatConfiguration: new ChatConfiguration(chatClient));

        await using var scenario = await reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Responds_Coherently));

        var result = await scenario.EvaluateAsync(messages, response);

        AssertAllMetricsPassed(result);
    }

    [TestMethod]
    public async Task Chat_Responds_Fluently()
    {
        await using var app = await _appHost.BuildAsync();
        await app.StartAsync();

        var chatClient = app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Write a short greeting for a new user of our application.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        var evaluators = new IEvaluator[] { new FluencyEvaluator() };

        var reportingConfig = DiskBasedReportingConfiguration.Create(
            storageRootPath: ".evaluation-results",
            evaluators: evaluators,
            chatConfiguration: new ChatConfiguration(chatClient));

        await using var scenario = await reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_Responds_Fluently));

        var result = await scenario.EvaluateAsync(messages, response);

        AssertAllMetricsPassed(result);
    }

    private static void AssertAllMetricsPassed(EvaluationResult result)
    {
        foreach (var metric in result.Metrics.Values)
        {
            if (metric is NumericMetric numericMetric)
            {
                Assert.IsNotNull(numericMetric.Interpretation,
                    $"Metric '{numericMetric.Name}' has no interpretation.");
                Assert.IsTrue(
                    numericMetric.Interpretation.Rating >= EvaluationRating.Good,
                    $"Metric '{numericMetric.Name}' rated '{numericMetric.Interpretation.Rating}', expected at least 'Good'.");
            }
        }
    }
}

